    if row == 0 and col == 0:  
        return grid[0][0]  
    if row < 0 or col < 0:  
        return -1  
    if row == 0:  
        return grid[row][col] + get_maxgold(grid, row, col - 1)  
    if col == 0:  
        return grid[row][col] + get_maxgold(grid, row - 1, col)  
